js:
var d = [];
var myUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var cate = (myUrl.split('#')[1] || 'tv').trim();
var realUrl = 'https://m.v.qq.com/x/m/channel/figure/' + cate;
var html = request(realUrl, {
  headers: {
    'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15',
    'Referer': 'https://m.v.qq.com/'
  }
});

var m = html.match(/__PINIA__\s*=\s*(\{[\s\S]*?\});?\s*<\/script>/);
if (m) {
  try {
    var pinia = eval('(' + m[1] + ')');
    function extractVideos(obj, depth) {
      if (!obj || depth > 8) return [];
      var res = [];
      if (Array.isArray(obj)) {
        for (var i = 0; i < obj.length; i++) {
          var item = obj[i];
          if (item && (item.title || item.playTitle) && (item.cid || item.vid)) {
            res.push(item);
          } else {
            res = res.concat(extractVideos(item, depth + 1));
          }
        }
      } else if (typeof obj === 'object') {
        var keys = Object.keys(obj);
        for (var j = 0; j < keys.length; j++) {
          res = res.concat(extractVideos(obj[keys[j]], depth + 1));
        }
      }
      return res;
    }

    var list = extractVideos(pinia, 0);
    var seen = {};
    for (var k = 0; k < list.length; k++) {
      var it = list[k];
      var cid = it.cid || it.vid;
      if (!cid || seen[cid]) continue;
      seen[cid] = true;
      var title = (it.title || it.playTitle || '').trim();
      var desc = (it.subTitle || it.secondTitle || it.desc || '').trim();
      var pic = it.pic || it.picUrl || it.imgUrl || it.verticalPicUrl || it.horizontalPicUrl || '';
      if (title) {
        d.push({
          title: title,
          desc: desc,
          pic_url: pic ? pic + '@Referer=https://v.qq.com/' : '',
          url: 'https://v.qq.com/x/cover/' + cid + '.html',
          col_type: 'movie_3'
        });
      }
    }
  } catch (e) {
    d.push({ title: '解析异常: ' + e.message, col_type: 'text_1' });
  }
}
setResult(d);

search_rule:
js:
var d = [];
var myUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var kw = (myUrl.split('?q=')[1] || '').trim();
var apiUrl = 'https://pbaccess.video.qq.com/trpc.videosearch.mobile_search.HttpMobileRecall/MbSearchHttp?vplatform=3';
var postBody = JSON.stringify({
  version: '15',
  clientType: 1,
  filterValue: '',
  query: kw,
  pageNum: 0,
  pageSize: 20
});

var resStr = post(apiUrl, {
  body: postBody,
  headers: {
    'Content-Type': 'application/json',
    'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15',
    'Referer': 'https://m.v.qq.com/'
  }
});

try {
  var json = JSON.parse(resStr);
  var items = (json.data && json.data.normalList && json.data.normalList.itemList) || [];
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    var doc = item.doc;
    var vInfo = item.videoInfo;
    if (!doc || !vInfo) continue;
    var cid = doc.id;
    var title = vInfo.title || '';
    var typeName = vInfo.typeName || '';
    var year = vInfo.year ? String(vInfo.year) : '';
    var actors = (vInfo.actors || []).join(' / ');
    var desc = [typeName, year, actors].filter(Boolean).join(' | ');
    var pic = vInfo.firstImgUrl || '';
    if (!pic && vInfo.episodeSites && vInfo.episodeSites.length > 0) {
      var epList = vInfo.episodeSites[0].episodeInfoList || [];
      if (epList.length > 0) pic = epList[0].imgUrl || '';
    }
    if (title && cid) {
      d.push({
        title: title,
        desc: desc,
        pic_url: pic ? pic + '@Referer=https://v.qq.com/' : '',
        url: 'https://v.qq.com/x/cover/' + cid + '.html',
        col_type: 'movie_3'
      });
    }
  }
} catch (e) {
  d.push({ title: '搜索解析异常: ' + e.message, col_type: 'text_1' });
}
setResult(d);

detail_find_rule:
js:
var d = [];
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var cidMatch = currentUrl.match(/(?:cover\/|cid=)([a-zA-Z0-9]+)/);
var cid = cidMatch ? cidMatch[1] : '';
var realUrl = cid ? ('https://m.v.qq.com/x/m/play?cid=' + cid) : currentUrl;

var html = request(realUrl, {
  headers: {
    'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15',
    'Referer': 'https://m.v.qq.com/'
  }
});

var m = html.match(/__PINIA__\s*=\s*(\{[\s\S]*?\});?\s*<\/script>/);
if (m) {
  try {
    var pinia = eval('(' + m[1] + ')');
    var coverInfo = (pinia.global && pinia.global.coverInfo) || {};
    var title = coverInfo.title || '腾讯精选影视';
    var desc = coverInfo.description || coverInfo.second_title || '';
    var pic = coverInfo.new_pic_vt || coverInfo.new_pic_hz || '';
    var episodes = (pinia.playlist && pinia.playlist.playList && pinia.playlist.playList.list) || [];

    // 1. 顶部大剧名卡片 (契约台账 #280: 注入剧名保护，防止 PC 播放历史丢失)
    d.push({
      title: '剧名：' + title,
      desc: desc,
      pic_url: pic ? pic + '@Referer=https://v.qq.com/' : '',
      url: currentUrl,
      col_type: 'pic_1_card'
    });

    // 2. 线路 Tab
    d.push({
      title: '【VIP 极速免嗅解析线】',
      col_type: 'text_1'
    });

    var lazyCode = ".js:(() => {\n  var targetUrl = (typeof input !== 'undefined' && input) ? input : (typeof MY_URL !== 'undefined' ? MY_URL : '');\n  var jxApis = [\n    'https://jx.playerjy.com/?url=',\n    'https://jx.jsonplayer.com/player/?url=',\n    'https://jx.m3u8.tv/jiexi/?url='\n  ];\n  var finalUrl = '';\n  for (var j = 0; j < jxApis.length; j++) {\n    try {\n      var jxUrl = jxApis[j] + encodeURIComponent(targetUrl);\n      var res = request(jxUrl, {\n        headers: {\n          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',\n          'Referer': targetUrl\n        }\n      });\n      var m3u8Match = res.match(/(https?:\\/\\/[^\"\\'\\s]+\\.m3u8[^\"\\'\\s]*)/);\n      if (m3u8Match) {\n        finalUrl = m3u8Match[1];\n        break;\n      }\n    } catch (_) {}\n  }\n  if (!finalUrl) {\n    finalUrl = jxApis[0] + encodeURIComponent(targetUrl);\n  }\n  return finalUrl + ';{Referer@https://v.qq.com/&&User-Agent@PC}';\n})()";

    var hasEp = false;
    for (var i = 0; i < episodes.length; i++) {
      var subList = episodes[i];
      if (Array.isArray(subList)) {
        for (var j = 0; j < subList.length; j++) {
          var ep = subList[j];
          var epTitle = ep.playTitle || ep.title || ('第' + (j + 1) + '集');
          var epVid = ep.vid;
          var epUrl = 'https://v.qq.com/x/cover/' + cid + '/' + epVid + '.html';
          d.push({
            title: epTitle,
            url: epUrl + '@lazyRule=' + lazyCode,
            col_type: 'text_3'
          });
          hasEp = true;
        }
      }
    }

    if (!hasEp) {
      d.push({
        title: '正片播放',
        url: currentUrl + '@lazyRule=' + lazyCode,
        col_type: 'text_3'
      });
    }
  } catch (e) {
    d.push({ title: '详情解析异常: ' + e.message, col_type: 'text_1' });
  }
} else {
  var fallbackLazy = ".js:(() => {\n  var targetUrl = (typeof input !== 'undefined' && input) ? input : (typeof MY_URL !== 'undefined' ? MY_URL : '');\n  var jxApis = [\n    'https://jx.playerjy.com/?url=',\n    'https://jx.jsonplayer.com/player/?url=',\n    'https://jx.m3u8.tv/jiexi/?url='\n  ];\n  var finalUrl = '';\n  for (var j = 0; j < jxApis.length; j++) {\n    try {\n      var jxUrl = jxApis[j] + encodeURIComponent(targetUrl);\n      var res = request(jxUrl, {\n        headers: {\n          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',\n          'Referer': targetUrl\n        }\n      });\n      var m3u8Match = res.match(/(https?:\\/\\/[^\"\\'\\s]+\\.m3u8[^\"\\'\\s]*)/);\n      if (m3u8Match) {\n        finalUrl = m3u8Match[1];\n        break;\n      }\n    } catch (_) {}\n  }\n  if (!finalUrl) {\n    finalUrl = jxApis[0] + encodeURIComponent(targetUrl);\n  }\n  return finalUrl + ';{Referer@https://v.qq.com/&&User-Agent@PC}';\n})()";
  d.push({
    title: '正片播放',
    url: currentUrl + '@lazyRule=' + fallbackLazy,
    col_type: 'text_3'
  });
}
setResult(d);
